/* ═════════════ 6.1 — Dotfiles trong một repo Git ═════════════ */
const B_INSTALL = bash("#!/usr/bin/env bash\n# install.sh — nối dotfiles vào $HOME bằng symlink. Chạy bao nhiêu lần cũng được (idempotent).\n#   ./install.sh        làm thật\n#   ./install.sh -n     chỉ in sẽ làm gì (dry-run)\nset -euo pipefail\nDOT=$(cd \"$(dirname \"$0\")\" && pwd)          # repo nằm đâu cũng được\nTHU=0; [ \"${1:-}\" = \"-n\" ] && THU=1\nBK=\"$HOME/.dotfiles-backup/$(date +%Y%m%d-%H%M%S)\"\n\n# nguồn trong repo           đích trong $HOME\nMAP=(\n  \"shell/bashrc               .bashrc\"\n  \"shell/zshrc                .zshrc\"\n  \"shell/dev.sh               .config/do-nghe/dev.sh\"\n  \"git/gitconfig              .gitconfig\"\n  \"git/ignore                 .config/git/ignore\"\n  \"tmux/tmux.conf             .tmux.conf\"\n  \"vscode/settings.json       .config/Code/User/settings.json\"\n)\n\nlam() { if [ $THU = 1 ]; then echo \"  (thu) $*\"; else \"$@\"; fi; }\n\nfor dong in \"${MAP[@]}\"; do\n  read -r nguon dich <<<\"$dong\"\n  src=\"$DOT/$nguon\"; dst=\"$HOME/$dich\"\n  if [ -L \"$dst\" ] && [ \"$(readlink \"$dst\")\" = \"$src\" ]; then\n    echo \"da dung  ~/$dich\"; continue                      # lần chạy thứ hai rơi vào đây\n  fi\n  if [ -e \"$dst\" ] || [ -L \"$dst\" ]; then                    # tệp thật hoặc symlink trỏ chỗ khác\n    echo \"sao luu  ~/$dich -> ${BK/#$HOME/~}/\"\n    lam mkdir -p \"$BK/$(dirname \"$dich\")\"\n    lam mv \"$dst\" \"$BK/$dich\"\n  fi\n  echo \"noi      ~/$dich -> $nguon\"\n  [ -d \"$(dirname \"$dst\")\" ] || lam mkdir -p \"$(dirname \"$dst\")\"\n  lam ln -s \"$src\" \"$dst\"\ndone\n\n# Tệp riêng của MÁY NÀY — không bao giờ vào repo, chỉ tạo nếu chưa có\nfor rieng in .gitconfig.local .config/do-nghe/local.sh; do\n  [ -e \"$HOME/$rieng\" ] || { echo \"tao rong ~/$rieng (dien tay, KHONG commit)\"; [ -d \"$(dirname \"$HOME/$rieng\")\" ] || lam mkdir -p \"$(dirname \"$HOME/$rieng\")\"; lam touch \"$HOME/$rieng\"; }\ndone\n");
const B_GITCONFIG = bash("# ~/.gitconfig — symlink tới dotfiles/git/gitconfig. KHÔNG có tên/email ở đây:\n# danh tính nằm trong ~/.gitconfig.local (riêng máy) và gitconfig-congty (bài 6.3).\n[include]\n\tpath = ~/.gitconfig.local\n[includeIf \"gitdir:~/work/\"]\n\tpath = ~/.config/git/congty.inc\n[init]\n\tdefaultBranch = main\n[pull]\n\trebase = true\n[fetch]\n\tprune = true\n[merge]\n\tconflictStyle = zdiff3\n[rebase]\n\tautoStash = true\n[diff]\n\talgorithm = histogram\n[rerere]\n\tenabled = true\n[core]\n\tautocrlf = input\n[alias]\n\tst = status -sb\n\tlg = log --oneline --graph --decorate -15\n\tlast = log -1 --stat\n\tunstage = restore --staged\n");
const B_BASHRC = bash("# ~/.bashrc — symlink tới dotfiles/shell/bashrc. Sửa ở repo, commit, mọi máy giống nhau.\ncase $- in *i*) ;; *) return ;; esac          # không tương tác (scp, script) ⇒ dừng sớm\nHISTCONTROL=ignoreboth                        # bỏ dòng trùng + dòng bắt đầu bằng dấu cách (bài 3.3)\nHISTSIZE=50000; HISTFILESIZE=50000; shopt -s histappend\nexport EDITOR=vim\n[ -d \"$HOME/.local/bin\" ] && PATH=\"$HOME/.local/bin:$PATH\"\n. \"$HOME/.config/do-nghe/dev.sh\"\n. \"$(dirname \"$(readlink -f \"${BASH_SOURCE[0]}\")\")/prompt.bash\"\n[ -f \"$HOME/.config/do-nghe/local.sh\" ] && . \"$HOME/.config/do-nghe/local.sh\"   # riêng máy này: proxy, token… KHÔNG trong repo\n");
const B_DOT_GITIGNORE = bash("# Lưới an toàn cuối cùng: kể cả lỡ chép vào repo, các tệp này không được add\n*.local\nlocal.sh\n.env*\nid_*\n!id_*.pub\n*.pem\n*.key\n.npmrc\n.netrc\nsettings-security.xml\ncredentials\nhosts.yml\n");
const B_GIT_IGNORE = bash("# ~/.config/git/ignore — bỏ qua cho MỌI repo trên máy này (không thay .gitignore của dự án)\n.DS_Store\nThumbs.db\n*.swp\n.idea/workspace.xml\n.idea/shelf/\n.vscode/*.log\n.env\n.env.*\n!.env.example\n");
