const O61_NAP = out("$ bash -ic 'alias gs; type mkcd' 2>/dev/null\nalias gs='git status -sb'\nmkcd is a function\nmkcd () \n{ \n    mkdir -p -- \"$1\" && cd -- \"$1\"\n}\n$ zsh -ic 'alias gs' 2>/dev/null\ngs='git status -sb'\n");
