/* ═════════════ 6.2 — Cài tự động bằng script ═════════════ */
const B_BOOTSTRAP = bash("#!/usr/bin/env bash\n# bootstrap.sh — máy mới: cài gói theo hệ điều hành, Node đúng phiên bản ghim (có kiểm sha256), rồi install.sh.\n# Chạy lại bao nhiêu lần cũng được: thứ gì đã đúng thì bỏ qua.\nset -euo pipefail\nDOT=$(cd \"$(dirname \"$0\")\" && pwd)\nlog() { printf '[%s] %s\\n' \"$(date +%H:%M:%S)\" \"$*\"; }\nco()  { command -v \"$1\" >/dev/null 2>&1; }\nSUDO=; [ \"$(id -u)\" -ne 0 ] && SUDO=sudo\n\n# ── 1. Gói hệ thống ─────────────────────────────────────────────\ncase \"$(uname -s)\" in\n  Linux)\n    if co apt-get; then\n      muon=$(grep -v '^#' \"$DOT/packages/apt.txt\" | sort -u)\n      co_roi=$(dpkg-query -W -f='${Package} ${Status}\\n' 2>/dev/null | awk '/ installed$/{print $1}' | sort -u)\n      thieu=$(comm -23 <(echo \"$muon\") <(echo \"$co_roi\"))\n      if [ -z \"$thieu\" ]; then log \"apt: du $(echo \"$muon\" | wc -l) goi\"\n      else log \"apt: cai $(echo $thieu)\"; $SUDO apt-get update -qq; $SUDO apt-get install -y -qq --no-install-recommends $thieu >/dev/null; fi\n    else log \"chua ho tro trinh quan ly goi nay — them nhanh dnf/pacman o day\"; exit 1; fi ;;\n  Darwin)\n    co brew || { log \"chua co Homebrew: cai theo https://brew.sh roi chay lai\"; exit 1; }\n    brew bundle check --file \"$DOT/packages/Brewfile\" >/dev/null && log \"brew: du\" || brew bundle --file \"$DOT/packages/Brewfile\" ;;\nesac\n# Ubuntu đặt tên khác: fdfind, batcat ⇒ tạo tên ngắn trong ~/.local/bin\nmkdir -p \"$HOME/.local/bin\"\nfor p in fdfind:fd batcat:bat; do g=${p%%:*} n=${p##*:}\n  co \"$g\" && [ ! -e \"$HOME/.local/bin/$n\" ] && ln -s \"$(command -v \"$g\")\" \"$HOME/.local/bin/$n\" && log \"ten ngan: $n -> $g\"\ndone\n\n# ── 2. Node đúng phiên bản ghim (packages/node-version), tải từ nodejs.org, kiểm sha256 ──\nNV=$(cat \"$DOT/packages/node-version\"); ND=\"$HOME/.local/node-v$NV\"\nif [ -x \"$ND/bin/node\" ]; then log \"node: da co v$NV\"\nelse\n  A=$(uname -m); case $A in x86_64) A=x64;; aarch64|arm64) A=arm64;; esac\n  OSN=$(uname -s | tr A-Z a-z); T=\"node-v$NV-$OSN-$A.tar.xz\"; TMP=$(mktemp -d)\n  log \"node: tai $T\"\n  curl -fsSLo \"$TMP/$T\" \"https://nodejs.org/dist/v$NV/$T\"\n  curl -fsSLo \"$TMP/SHASUMS256.txt\" \"https://nodejs.org/dist/v$NV/SHASUMS256.txt\"\n  (cd \"$TMP\" && grep \" $T\\$\" SHASUMS256.txt | sha256sum -c --quiet) || { log \"node: SAI sha256 — dung lai\"; exit 1; }\n  log \"node: sha256 khop\"\n  mkdir -p \"$ND\"; tar -xJf \"$TMP/$T\" -C \"$ND\" --strip-components=1; rm -r \"$TMP\"\nfi\nfor b in node npm npx; do ln -sfn \"$ND/bin/$b\" \"$HOME/.local/bin/$b\"; done\n\n# ── 3. Dotfiles ─────────────────────────────────────────────────\n\"$DOT/install.sh\" | grep -v '^da dung' || true\nlog \"xong: $(git --version | cut -d' ' -f3) · java $(java -version 2>&1 | awk -F'\"' 'NR==1{print $2}') · node $(\"$HOME/.local/bin/node\" -v)\"\n");
