const B_SSH_CONFIG = bash("# dotfiles/ssh/config.example — chép (không symlink) thành ~/.ssh/config rồi chmod 600.\n# Chỉ có CẤU HÌNH. Khoá riêng (id_*) không bao giờ nằm trong repo.\nHost *\n  IdentitiesOnly yes          # chỉ đưa khoá ghi trong IdentityFile, không đưa cả túi khoá của agent\n  AddKeysToAgent yes          # lần đầu hỏi passphrase, sau đó agent giữ\n  ServerAliveInterval 60\n  # macOS: thêm  UseKeychain yes  để Keychain nhớ passphrase\n\n# Tài khoản cá nhân: git@github.com:ten-ban/...\nHost github.com\n  User git\n  IdentityFile ~/.ssh/id_canhan\n\n# Tài khoản công ty trên CÙNG github.com: dùng bí danh git@github-congty:to-chuc/...\nHost github-congty\n  HostName github.com\n  User git\n  IdentityFile ~/.ssh/id_congty\n");
