const B_PROFILE_PS = bash("# dotfiles/windows/profile.ps1 — nạp từ $PROFILE bằng một dòng:  . \"$HOME\\dotfiles\\windows\\profile.ps1\"\nSet-Alias -Name grep -Value Select-String          # thói quen bash, nhưng nhớ: ra ĐỐI TƯỢNG, không phải dòng chữ\nfunction gs { git status -sb }\nfunction gl { git log --oneline --graph -12 }\nfunction mkcd([string]$d) { New-Item -ItemType Directory -Force $d | Out-Null; Set-Location $d }\n# cong <số>: tiến trình nào đang nghe cổng (Windows: Get-NetTCPConnection; PS 7 trên Linux/Mac không có lệnh này)\nfunction cong([int]$p) {\n  if (Get-Command Get-NetTCPConnection -ErrorAction SilentlyContinue) {\n    Get-NetTCPConnection -LocalPort $p -State Listen | ForEach-Object { Get-Process -Id $_.OwningProcess }\n  } else { lsof -nP \"-iTCP:$p\" -sTCP:LISTEN }\n}\n$local = Join-Path $HOME '.config/do-nghe/local.ps1'                 # riêng máy: proxy, token… KHÔNG trong repo\nif (Test-Path $local) { . $local }\n");
const B_BOOT_PS = bash("# dotfiles/windows/bootstrap.ps1 — máy Windows mới: winget import + nối profile + cấu hình Git. Chạy lại được.\n#   pwsh -File windows\\bootstrap.ps1 -WhatIf     chỉ in sẽ làm gì\n[CmdletBinding(SupportsShouldProcess)]\nparam()\n$ErrorActionPreference = 'Stop'\n$Dot = Split-Path -Parent $PSScriptRoot\n\n# 1. Gói: winget import bỏ qua gói đã có\nif ($IsWindows -and (Get-Command winget -ErrorAction SilentlyContinue)) {\n  if ($PSCmdlet.ShouldProcess('winget.json', 'winget import')) {\n    winget import -i (Join-Path $Dot 'packages/winget.json') --accept-package-agreements --accept-source-agreements --ignore-unavailable\n  }\n} else { Write-Warning 'Khong co winget (khong phai Windows?) — bo qua buoc cai goi' }\n\n# 2. Profile PowerShell: thêm ĐÚNG MỘT dòng nạp, không ghi đè profile có sẵn\n$dong = \". `\"$(Join-Path $Dot 'windows/profile.ps1')`\"\"\nif (-not (Test-Path $PROFILE)) { New-Item -ItemType File -Force $PROFILE -WhatIf:$WhatIfPreference | Out-Null }\nif ((Test-Path $PROFILE) -and (Select-String -Path $PROFILE -SimpleMatch $dong -Quiet)) { Write-Host \"da dung  $PROFILE\" }\nelseif ($PSCmdlet.ShouldProcess($PROFILE, \"them dong nap $dong\")) { Add-Content -Path $PROFILE -Value $dong; Write-Host \"noi      $PROFILE\" }\n\n# 3. Git: dùng chung gitconfig của dotfiles qua include (Windows không cần symlink — symlink cần Developer Mode)\n$gc = Join-Path $HOME '.gitconfig'\n$inc = (Join-Path $Dot 'git/gitconfig') -replace '\\\\', '/'\nif ((Test-Path $gc) -and (Select-String -Path $gc -SimpleMatch $inc -Quiet)) { Write-Host \"da dung  $gc\" }\nelseif ($PSCmdlet.ShouldProcess($gc, \"include $inc\")) { git config --global --add include.path $inc; Write-Host \"noi      $gc\" }\n");
