const B_KIEM65 = bash("#!/usr/bin/env bash\n# kiem65.sh — chấm \"máy mới\" sau lab 6.5. Chạy bằng user thường trên máy vừa dựng:  bash kiem65.sh\n# In 10 dòng [ĐẠT]/[CHƯA], mã thoát = số mục chưa đạt.\nD=~/dotfiles; W=~/work; T=0; Dat=0\nok() { T=$((T+1)); if [ \"$1\" -eq 0 ]; then Dat=$((Dat+1)); echo \"[ĐẠT]  $2\"; else echo \"[CHƯA] $2\"; fi; }\nlk() { [ -L \"$1\" ] && case \"$(readlink \"$1\")\" in \"$D\"/*) return 0;; esac; return 1; }\nlk ~/.bashrc && lk ~/.gitconfig && lk ~/.config/git/ignore;            ok $? \"1. .bashrc, .gitconfig, git/ignore là symlink vào ~/dotfiles\"\n\"$D/bootstrap.sh\" 2>&1 | grep -qE '^\\[[0-9:]+\\] (apt: du|brew: du)' && ! \"$D/bootstrap.sh\" 2>&1 | grep -qE 'apt: cai|node: tai|^noi '\n                                                                        ok $? \"2. bootstrap.sh chạy lại không cài/nối gì (luỹ đẳng)\"\ngit config --show-origin user.email | grep -q \"$HOME/.gitconfig.local\"; ok $? \"3. email cá nhân nằm trong ~/.gitconfig.local, không trong repo\"\n( [ -n \"$(ls -d $W/*/.git 2>/dev/null)\" ] && for r in $W/*/; do [ -d \"$r/.git\" ] || continue; e=$(git -C \"$r\" config user.email); [ -n \"$e\" ] && [ \"$e\" != \"$(git config --file ~/.gitconfig.local user.email)\" ] || exit 1; done )\n                                                                        ok $? \"4. repo dưới ~/work dùng email công ty (includeIf)\"\nn=0; for k in ~/.ssh/id_*; do case $k in *.pub) continue;; esac; n=$((n+1)); ssh-keygen -y -P \"\" -f \"$k\" >/dev/null 2>&1 && n=99; done\n[ $n -ge 1 ] && [ $n -lt 99 ] && grep -q '^ *IdentitiesOnly yes' ~/.ssh/config 2>/dev/null\n                                                                        ok $? \"5. khoá SSH đều có passphrase + ~/.ssh/config có IdentitiesOnly yes\"\n! git -C \"$D\" log -p --all | grep -qE 'PRIVATE KEY-----|ghp_[A-Za-z0-9]{30,}|AKIA[0-9A-Z]{16}|npm_[A-Za-z0-9]{30,}|_authToken='\n                                                                        ok $? \"6. lịch sử dotfiles không có khoá riêng/token\"\njava -version 2>&1 | grep -q 'version \"21'; ok $? \"7. java 21 trên PATH\"\n[ \"$(node -v 2>/dev/null)\" = \"v$(cat \"$D/packages/node-version\")\" ];  ok $? \"8. node đúng packages/node-version\"\n(cd \"$W/gear-mini\" && ./mvnw -q -B test >/tmp/kiem65-mvn.log 2>&1);    ok $? \"9. gear-mini: ./mvnw test xanh\"\n(cd \"$W/api-ojt\" && npm test >/tmp/kiem65-npm.log 2>&1);                ok $? \"10. api-ojt: npm test xanh\"\necho \"== $Dat/$T mục đạt\"; exit $((T-Dat))\n");
const B_LOI_GIAI65 = bash("#!/usr/bin/env bash\n# loi-giai65.sh — lời giải mẫu lab 6.5, chạy trên \"máy mới\" (user sv, có sudo + curl, CÓ mạng).\n# Đối số: URL repo dotfiles, URL gear-mini, URL api-ojt (trên máy thật: git@github.com:… / git@github-congty:…)\nset -euo pipefail; export TZ=ICT-7\nDOTS=$1 GEAR=$2 API=$3; BD=$(date +%s)\nmoc() { printf '[%s] (+%3ss) %s\\n' \"$(date +%H:%M:%S)\" $(( $(date +%s) - BD )) \"$*\"; }\nmoc \"0. buoc 0: git\"\ncommand -v git >/dev/null || { sudo apt-get update -qq && sudo apt-get install -y -qq --no-install-recommends git >/dev/null 2>&1; }\nmoc \"1. clone dotfiles + bootstrap\"\ngit clone -q \"$DOTS\" ~/dotfiles && ~/dotfiles/bootstrap.sh | grep -E 'apt:|node:|xong' || true\nexport PATH=\"$HOME/.local/bin:$PATH\"\nmoc \"2. danh tinh: ~/.gitconfig.local + congty.inc + khoa SSH co passphrase\"\ngit config --file ~/.gitconfig.local user.name \"SV OJT\"; git config --file ~/.gitconfig.local user.email sv.ojt@example.com\nmkdir -p ~/.config/git && grep -v '^#' ~/dotfiles/git/congty.inc.example > ~/.config/git/congty.inc\nmkdir -p ~/.ssh && chmod 700 ~/.ssh\nfor k in canhan congty; do [ -f ~/.ssh/id_$k ] || ssh-keygen -q -t ed25519 -C \"sv $k\" -f ~/.ssh/id_$k -N \"$(eval echo \\$PASS_${k^^})\"; done\n[ -f ~/.ssh/config ] || { cp ~/dotfiles/ssh/config.example ~/.ssh/config; chmod 600 ~/.ssh/config; }\nmoc \"3. clone hai du an vao ~/work\"\nmkdir -p ~/work; git clone -q \"$GEAR\" ~/work/gear-mini; git clone -q \"$API\" ~/work/api-ojt\nmoc \"4. gear-mini: ./mvnw test (lan dau tai Maven + thu vien)\"\n(cd ~/work/gear-mini && ./mvnw -B test 2>&1 | grep -E '^\\[INFO\\] (Tests run:|BUILD)|ERROR' | tail -2) || true\nmoc \"5. api-ojt: npm ci + npm test\"\n(cd ~/work/api-ojt && npm ci --no-audit --no-fund 2>&1 | grep -E '^added' && npm test 2>&1 | grep -E '^# (tests|pass|fail)')\nmoc \"6. cham\"\nbash ~/dotfiles/../kiem65.sh 2>/dev/null || bash /lab/lab65/kiem65.sh\nmoc \"xong\"\n");
const B_CHECKLIST = bash("# Checklist máy dev — ngày đầu OJT\nĐiền ngày, đánh [x] khi XONG và có bằng chứng (lệnh + kết quả). Không ghi mật khẩu/token vào tệp này.\n\n## A. Tài khoản & quy định (sáng ngày 1)\n- [ ] Đọc + ký NDA, quy định an ninh thông tin; hỏi: có được dùng tài khoản GitHub cá nhân trên máy này không?\n- [ ] Email công ty, VPN, máy chủ Git (GitLab/GitHub org), Jira/Backlog, chat nhóm: đăng nhập được, bật 2FA\n- [ ] Hỏi công cụ AI nào ĐƯỢC PHÉP dùng với mã khách hàng (bài 2.6) — ghi tên công cụ + phạm vi\n- [ ] Hỏi IT: Docker Desktop có giấy phép công ty không? Nếu không: Docker Engine trong WSL2 / Podman / Rancher\n\n## B. Máy (bài 6.2–6.4)\n- [ ] Bước 0: có Git; clone dotfiles (nếu quy định cho phép) → ./bootstrap.sh → chạy lại lần 2 không cài gì\n- [ ] JDK đúng hãng + bản dự án dùng: java -version = ______ ; Node theo .nvmrc: node -v = ______\n- [ ] Proxy công ty (nếu có): HTTPS_PROXY, ~/.m2/settings.xml <proxies>, .npmrc proxy, Docker → để trong local.sh, KHÔNG commit\n- [ ] Kho nội bộ: Nexus/Artifactory trong ~/.m2/settings.xml (mật khẩu mã hoá bằng mvn --encrypt-password), registry npm nội bộ\n- [ ] Windows: PowerShell 7 + Windows Terminal, execution policy CurrentUser RemoteSigned, WSL2 + mã ở ~ trong WSL\n\n## C. Danh tính Git (bài 6.3)\n- [ ] Khoá SSH MỚI cho công ty, có passphrase; thêm vào máy chủ Git công ty; ssh -T chào đúng tài khoản\n- [ ] Repo công ty nằm dưới ~/work/ ⇒ git config user.email = email công ty (includeIf)\n- [ ] Ký commit nếu dự án yêu cầu (gpg.format ssh); git log --show-signature = Good\n- [ ] Hook của dự án đã cài (pre-commit, commit-msg có mã ticket) — bài 5.1\n\n## D. Dự án (ngày 1–2)\n- [ ] Clone đúng URL (bí danh github-congty nếu cùng GitHub); đọc README, CONTRIBUTING, quy ước nhánh/commit\n- [ ] Build + test XANH trên máy mình: ./mvnw test (hoặc ./gradlew test), npm ci && npm test — ghi thời gian\n- [ ] Chạy ứng dụng cục bộ, gọi được /health; có bộ request .http/Postman của nhóm (bài 2.5)\n- [ ] Cơ sở dữ liệu: tài khoản CHỈ-ĐỌC cho môi trường chung; DB cục bộ bằng Docker cho việc thử\n- [ ] IntelliJ: SDK + language level đúng, Maven dùng wrapper, code style của dự án, SonarQube for IDE nối máy chủ của nhóm\n- [ ] .gitignore dự án có .env, .idea/workspace.xml…; tệp bỏ qua toàn máy (~/.config/git/ignore) đã bật\n\n## E. Cuối ngày 1\n- [ ] Commit đầu tiên (sửa README/typo) đi qua đủ quy trình: nhánh → MR/PR → review → merge\n- [ ] Ghi lại chỗ vướng + ai đã giúp; cập nhật dotfiles (git -C ~/dotfiles status trống sau khi commit)\n");
const B_APP_TEST = bash("import { test } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { app } from '../src/app.js';\n\ntest('GET /health tra UP', async () => {\n  const sv = app.listen(0); const { port } = sv.address();\n  const r = await fetch(`http://127.0.0.1:${port}/health`);\n  assert.equal(r.status, 200); assert.equal((await r.json()).status, 'UP');\n  sv.close();\n});\ntest('GET /api/tickets/7', async () => {\n  const sv = app.listen(0); const { port } = sv.address();\n  const body = await (await fetch(`http://127.0.0.1:${port}/api/tickets/7`)).json();\n  assert.deepEqual(body, { id: 7, title: 'Cai may ngay dau', done: false });\n  sv.close();\n});\n");
